const crypto = require('crypto');
const http = require('http');
const fs = require('fs');

const STATE_FILE = '/memory/project_rag_state.json';

function uuidv5(name) {
  const nsHex = '6ba7b8109dad11d180b400c04fd430c8';
  const nsBuf = Buffer.from(nsHex, 'hex');
  const nameBuf = Buffer.from(name, 'utf8');
  const hash = crypto.createHash('sha1').update(Buffer.concat([nsBuf, nameBuf])).digest();
  hash[6] = (hash[6] & 0x0f) | 0x50;
  hash[8] = (hash[8] & 0x3f) | 0x80;
  const h = hash.slice(0, 16).toString('hex');
  return h.slice(0,8) + '-' + h.slice(8,12) + '-' + h.slice(12,16) + '-' + h.slice(16,20) + '-' + h.slice(20,32);
}

function httpCall(method, host, port, urlPath, body) {
  return new Promise(function(resolve, reject) {
    const data = JSON.stringify(body);
    const req = http.request(
      { host: host, port: port, path: urlPath, method: method, headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(data) } },
      function(res) {
        let buf = '';
        res.on('data', function(c) { buf += c; });
        res.on('end', function() { try { resolve(JSON.parse(buf)); } catch(e) { resolve({}); } });
      }
    );
    req.on('error', reject);
    req.write(data);
    req.end();
  });
}

let state;
try {
  const raw = JSON.parse(fs.readFileSync(STATE_FILE, 'utf8'));
  state = raw.files !== undefined ? raw : { files: raw, dirty_dirs: [], dirty_projects: [], structure_changed: false };
} catch (e) {
  return [{ json: { status: 'no_state', processed: 0 } }];
}

const dirtyDirs = state.dirty_dirs || [];
if (dirtyDirs.length === 0) {
  return [{ json: { status: 'nothing_to_do', processed: 0 } }];
}

// Process deepest dirs first so parent dirs aggregate already-updated children
const sortedDirs = [...dirtyDirs].sort(function(a, b) {
  return b.split('/').length - a.split('/').length;
});

const processed = [];
const failedDirs = [];
const newDirtyProjects = new Set(state.dirty_projects || []);

for (const dirHierarchyId of sortedDirs) {
  try {
    // Query file-level summaries for this directory
    const scrollRes = await httpCall('POST', 'qdrant', 6333, '/collections/project_rag/points/scroll', {
      filter: {
        must: [
          { key: 'metadata.level', match: { value: 'file' } },
          { key: 'metadata.parent_id', match: { value: dirHierarchyId } }
        ]
      },
      limit: 100,
      with_payload: true,
      with_vector: false
    });

    const points = (scrollRes.result && scrollRes.result.points) || [];
    if (points.length === 0) {
      // No file summaries yet — keep dir dirty, try next run
      failedDirs.push(dirHierarchyId);
      continue;
    }

    const fileMetas = points.map(function(p) { return p.payload && p.payload.metadata ? p.payload.metadata : p.payload || {}; });
    const summaryLines = fileMetas.map(function(m) {
      return (m.filename || '?') + ': ' + (m.purpose || m.summary || '');
    }).join('\n');

    const project = dirHierarchyId.split('/')[0];
    const dirName = dirHierarchyId.split('/').pop();
    const parentParts = dirHierarchyId.split('/');
    const parentId = parentParts.length > 1 ? parentParts.slice(0, -1).join('/') : project;

    // Synthesize directory summary
    const chatRes = await httpCall('POST', 'host.docker.internal', 11434, '/api/chat', {
      model: 'qwen2.5-coder:14b',
      messages: [
        { role: 'system', content: 'You summarize software project directories for a semantic search index. Output STRICT JSON only, no markdown fences.' },
        { role: 'user', content: 'Project: ' + project + '\nDirectory: ' + dirHierarchyId + '\nFiles and their purposes:\n' + summaryLines + '\n\nRespond with STRICT JSON: {"summary": "<one sentence>", "purpose": "<short phrase>", "responsibilities": ["<verb phrase>"], "key_files": ["<filename>"], "topics": ["<keyword>"]}' }
      ],
      stream: false,
      options: { temperature: 0.1, num_predict: 300 }
    });

    let parsed = {};
    try {
      const rawText = (chatRes.message && chatRes.message.content) || '';
      parsed = JSON.parse(rawText.replace(/```json|```/g, '').trim());
    } catch (e) {
      parsed = {
        summary: 'Directory ' + dirName + ' containing ' + fileMetas.length + ' files',
        purpose: dirName,
        responsibilities: [],
        key_files: fileMetas.slice(0, 3).map(function(m) { return m.filename || ''; }),
        topics: []
      };
    }

    // Embed
    const embedText = [
      'Directory: ' + dirHierarchyId,
      'Purpose: ' + (parsed.purpose || parsed.summary || ''),
      parsed.responsibilities && parsed.responsibilities.length ? 'Responsibilities: ' + parsed.responsibilities.join(', ') : '',
      parsed.topics && parsed.topics.length ? 'Topics: ' + parsed.topics.join(', ') : ''
    ].filter(Boolean).join('\n');

    const embedRes = await httpCall('POST', 'host.docker.internal', 11434, '/api/embed', {
      model: 'qwen3-embedding:4b', input: embedText
    });
    const vector = (embedRes.embeddings || [[]])[0];

    if (!vector || !vector.length) {
      const line = new Date().toISOString() + '\tdir_embed_empty\t' + dirHierarchyId + '\n';
      try { fs.appendFileSync('/memory/project_rag_failures.log', line); } catch (err) {}
      failedDirs.push(dirHierarchyId);
      continue;
    }

    const contentText = [
      'Purpose: ' + (parsed.purpose || parsed.summary || ''),
      parsed.responsibilities && parsed.responsibilities.length ? 'Responsibilities: ' + parsed.responsibilities.join(', ') : '',
      parsed.key_files && parsed.key_files.length ? 'Key files: ' + parsed.key_files.join(', ') : '',
      parsed.topics && parsed.topics.length ? 'Topics: ' + parsed.topics.join(', ') : ''
    ].filter(Boolean).join('\n');

    // Upsert directory summary point
    const pointId = uuidv5('dir:' + dirHierarchyId);
    await httpCall('PUT', 'qdrant', 6333, '/collections/project_rag/points?wait=false', {
      points: [{
        id: pointId,
        vector: vector,
        payload: {
          content: contentText,
          metadata: {
            hierarchy_id: dirHierarchyId,
            level: 'directory',
            parent_id: parentId,
            project: project,
            summary: parsed.summary || '',
            purpose: parsed.purpose || '',
            responsibilities: parsed.responsibilities || [],
            key_files: parsed.key_files || [],
            topics: parsed.topics || [],
            children: fileMetas.map(function(m) { return m.hierarchy_id; }).filter(Boolean),
            updated_at: new Date().toISOString()
          }
        }
      }]
    });

    newDirtyProjects.add(project);
    processed.push(dirHierarchyId);
  } catch (e) {
    const line = new Date().toISOString() + '\tdir_synthesis_error\t' + dirHierarchyId + '\t' + String(e) + '\n';
    try { fs.appendFileSync('/memory/project_rag_failures.log', line); } catch (err) {}
    failedDirs.push(dirHierarchyId);
  }
}

// Update state: clear processed dirs, keep failed, accumulate dirty projects
state.dirty_dirs = failedDirs;
state.dirty_projects = Array.from(newDirtyProjects);
fs.writeFileSync(STATE_FILE, JSON.stringify(state, null, 2));

return [{ json: { status: 'done', processed: processed.length, failed: failedDirs.length, dirty_projects: Array.from(newDirtyProjects) } }];
